import requests

hostname = "<HOSTNAME>"
username = "<USERNAME>"
password = "<PASSWORD>"

access_token = requests.post(f"https://{hostname}/v1/auth/token", data={"username": username, "password": password}).json()["access_token"]

requests.post(f"https://{hostname}/v1/plans/search",
    json={
    "plan_ids": [
        123,
        456
    ]
},
    headers={"Authorization": f"Bearer {access_token}"}
)

